import os
import subprocess
import tempfile

def setup_env(req_path='requirements.txt', env_dir='venv'):
    if not os.path.exists(env_dir):
        subprocess.run(['python', '-m', 'venv', env_dir], check=True)
    pip = os.path.join(env_dir, 'bin', 'pip')
    subprocess.run([pip, 'install', '-r', req_path], check=True)
    return os.path.join(env_dir, 'bin', 'python')

if __name__ == '__main__':
    interpreter = setup_env()
    print('Active interpreter:', interpreter)

